WITH filtered AS (SELECT *, CASE WHEN budget >= 4019000 THEN 'High' WHEN budget >= 1073000 THEN 'Medium' ELSE 'Low' END AS budget_band FROM departments WHERE location <> 'Berlin' AND location IS NOT NULL) SELECT *, MAX(budget) OVER w_recent AS running_max_budget, SUM(budget) OVER w_recent AS running_sum_budget, COUNT(budget) OVER w_recent AS running_count_budget, AVG(budget) OVER w_recent AS running_avg_budget FROM filtered WINDOW w_recent AS (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
